with matched_keys as (select account_id from transactions intersect all select account_id from transactions where amount between 1300 and 3100), kept_rows as (select s.* from transactions s join matched_keys k on s.account_id = k.account_id) select account_id, txn_type, amount, case when txn_type rlike '^(CREDIT|FEE)$' then 'GROUP_B' when txn_type rlike '^(DEBIT|REFUND)$' then 'PRIORITY' else 'CORE' end as txn_type_zone from kept_rows
